1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags the newly built owner as a possible (soft) duplicate of an existing one. A soft match is an
9	 * existing owner in the same household — same deterministic {@link Owner#getHouseholdId() householdId}
10	 * (last name and postcode) — but reachable on a different telephone. When one is found the earliest
11	 * such owner's id is recorded via {@link Owner#setPossibleDuplicateOf(Integer)}, which drives the
12	 * {@code possibleDuplicate} / {@code possibleDuplicateOf} response fields.
13	 *
14	 * <p>A {@link DeclaredHouseholdMember declared household member} — one admitted into an occupied
15	 * household via {@code sharesHousehold} — is deliberate, not suspected, so it is never flagged. Every
16	 * other same-household owner reachable on a different telephone is admitted as an ordinary member and
17	 * flagged here. Owners without a postcode belong to no household and never soft-match.
18	 *
19	 * <p>Runs after {@link EnsureUniqueIdentity} and before {@link SaveOwner}, so the flag is persisted
20	 * with the owner.
21	 */
22	public class DetectPossibleDuplicate {
23	
24	    public void service(@Val Owner owner, @Val DeclaredHouseholdMember declaredMember,
25	            OwnerRepository ownerRepository) {
26	        if (declaredMember != null) {
27	            return;
28	        }
29	        String householdId = owner.getHouseholdId();
30	        if (householdId == null || householdId.isBlank()) {
31	            return;
32	        }
33	        ownerRepository.findByLastName(owner.getLastName()).stream()
34	            .filter(existing -> householdId.equals(existing.getHouseholdId())
35	                && existing.getTelephone() != null
36	                && !existing.getTelephone().equals(owner.getTelephone()))
37	            .map(Owner::getId)
38	            .filter(id -> id != null)
39	            .min(Integer::compareTo)
40	            .ifPresent(owner::setPossibleDuplicateOf);
41	    }
42	}
