1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Locale;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.model.Sha256;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.util.StringUtils;
10	
11	/**
12	 * Household identity shared by the create-owner steps. A household is the set of owners with the same
13	 * last name (normalized case-insensitively with collapsed whitespace) and the same postcode. Its
14	 * {@code householdId} is derived deterministically from those two values, so any two owners with the
15	 * same last name and postcode share it automatically without an explicit link. Used by
16	 * {@link AssignHouseholdId} to stamp each owner and by the steps that key off the household —
17	 * {@link MarkDeclaredHouseholdMember}, {@link CountHouseholdMembers} and {@link CapMembershipLevel} —
18	 * via {@link #existingMembers}.
19	 */
20	final class Household {
21	
22	    /** The number of leading hex characters of the SHA-256 digest that form a household id. */
23	    private static final int ID_LENGTH = 12;
24	
25	    private Household() {
26	    }
27	
28	    /** Case-insensitive form with leading/trailing and repeated inner whitespace collapsed to one space. */
29	    static String normalizeLastName(String lastName) {
30	        return lastName == null ? "" : lastName.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
31	    }
32	
33	    /**
34	     * The deterministic household id for the given last name and postcode: the first
35	     * {@value #ID_LENGTH} hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
36	     * Returns {@code null} when no postcode is supplied, since a household is keyed on postcode and an
37	     * owner without one belongs to no household.
38	     */
39	    static String idFor(String lastName, String postcode) {
40	        if (!StringUtils.hasText(postcode)) {
41	            return null;
42	        }
43	        return Sha256.hex(normalizeLastName(lastName) + '|' + postcode).substring(0, ID_LENGTH);
44	    }
45	
46	    /**
47	     * The existing owners sharing the given owner's household, i.e. those already persisted with the
48	     * same {@link Owner#getHouseholdId() householdId}. The owner itself is not yet saved, so it never
49	     * appears. An owner belonging to no household (no id) has no existing members.
50	     */
51	    static List<Owner> existingMembers(Owner owner, OwnerRepository ownerRepository) {
52	        String householdId = owner.getHouseholdId();
53	        if (householdId == null || householdId.isBlank()) {
54	            return List.of();
55	        }
56	        return ownerRepository.findByLastName(owner.getLastName()).stream()
57	            .filter(member -> householdId.equals(member.getHouseholdId()))
58	            .toList();
59	    }
60	}
