374	    }
375	
376	    protected Set<Pet> getPetsInternal() {
377	        if (this.pets == null) {
378	            this.pets = new HashSet<>();
379	        }
380	        return this.pets;
381	    }
382	
383	    protected void setPetsInternal(Set<Pet> pets) {
384	        this.pets = pets;
385	    }
386	
387	    public List<Pet> getPets() {
388	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
389	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
390	        return Collections.unmodifiableList(sortedPets);
391	    }
392	
393	    public void setPets(List<Pet> pets) {
394	        this.pets = new HashSet<>(pets);
395	    }
396	
397	    public void addPet(Pet pet) {
398	        getPetsInternal().add(pet);
399	        pet.setOwner(this);
400	    }
401	
402	    /**
403	     * Return the Pet with the given name, or null if none found for this Owner.
404	     *
405	     * @param name to test
406	     * @return true if pet name is already in use
407	     */
408	    public Pet getPet(String name) {
409	        return getPet(name, false);
410	    }
411	
412	    /**
413	     * Return the Pet with the given name, or null if none found for this Owner.
414	     *
415	     * @param name to test
416	     * @return true if pet name is already in use
417	     */
418	    public Pet getPet(String name, boolean ignoreNew) {
419	        name = name.toLowerCase();
420	        for (Pet pet : getPetsInternal()) {
421	            if (!ignoreNew || !pet.isNew()) {
422	                String compName = pet.getName();
423	                compName = compName.toLowerCase();
424	                if (compName.equals(name)) {
425	                    return pet;
426	                }
427	            }
428	        }
429	        return null;
430	    }
431	
432	    public Pet getPet(Integer petId) {
433	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
434	    }
