1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * E.164 telephone-number metadata and human-readable formatting. Holds the known country codes and
7	 * the national-number length each requires, and renders a stored compact E.164 number for people to
8	 * read: the country code, a space, then the national digits grouped in threes (so
9	 * {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
10	 *
11	 * <p>It is the single source of truth for E.164 country-code knowledge, shared by the request-time
12	 * normalization that produces the compact number and by the {@link Owner#getTelephoneDisplay()
13	 * display} derived from it.
14	 */
15	public final class E164 {
16	
17	    /** Country code (digits, no {@code '+'}) to the exact national-number length it requires. */
18	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
19	
20	    /** National digits are shown in groups of this many, separated by spaces. */
21	    private static final int GROUP_SIZE = 3;
22	
23	    private E164() {
24	    }
25	
26	    /**
27	     * The national-number length required for {@code countryCode}, or {@code null} when no rule is
28	     * known for it.
29	     */
30	    public static Integer nationalLength(String countryCode) {
31	        return NATIONAL_LENGTHS.get(countryCode);
32	    }
33	
34	    /**
35	     * The known country code that prefixes {@code digits} (the E.164 body: country code plus national
36	     * number, no {@code '+'}), taken as the longest matching known country code, or {@code null} when
37	     * none is known.
38	     */
39	    public static String countryCodeOf(String digits) {
40	        String match = null;
41	        for (String code : NATIONAL_LENGTHS.keySet()) {
42	            if (digits.startsWith(code) && (match == null || code.length() > match.length())) {
43	                match = code;
44	            }
45	        }
46	        return match;
47	    }
48	
49	    /**
50	     * Formats a compact E.164 number for humans as the country code, a space, then the national
51	     * digits grouped in threes (e.g. {@code "+61412345678"} to {@code "+61 412 345 678"}). Returns
52	     * the input unchanged when it is {@code null}, not {@code '+'}-prefixed, or carries a country code
53	     * with no known length (so it cannot be split reliably).
54	     */
55	    public static String display(String e164) {
56	        if (e164 == null || !e164.startsWith("+")) {
57	            return e164;
58	        }
59	        String digits = e164.substring(1);
60	        String countryCode = countryCodeOf(digits);
61	        if (countryCode == null) {
62	            return e164;
63	        }
64	        return "+" + countryCode + " " + groupInThrees(digits.substring(countryCode.length()));
65	    }
66	
67	    /** Groups {@code national} into runs of {@link #GROUP_SIZE} digits separated by single spaces. */
68	    private static String groupInThrees(String national) {
69	        StringBuilder grouped = new StringBuilder();
70	        for (int i = 0; i < national.length(); i++) {
71	            if (i > 0 && i % GROUP_SIZE == 0) {
72	                grouped.append(' ');
73	            }
74	            grouped.append(national.charAt(i));
75	        }
76	        return grouped.toString();
77	    }
78	}
