3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Computes the SHA-256 digest of a string as upper-case hexadecimal. Shared by the derived
9	 * identities that hash owner attributes (the customer code and the household id).
10	 */
11	public final class Sha256 {
12	
13	    private Sha256() {
14	    }
15	
16	    /** The full upper-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
17	    public static String hex(String value) {
18	        byte[] digest;
19	        try {
20	            digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
21	        } catch (NoSuchAlgorithmException e) {
22	            throw new IllegalStateException("SHA-256 unavailable", e);
23	        }
24	        StringBuilder hex = new StringBuilder(digest.length * 2);
25	        for (byte b : digest) {
26	            hex.append(String.format("%02X", b));
27	        }
28	        return hex.toString();
29	    }
30	}
