1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import org.springframework.samples.petclinic.model.E164;
6	
7	/**
8	 * Converts a raw telephone into E.164 form. A leading {@code '+'} and country code are kept
9	 * when present; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
10	 * is dropped from the national digits. Spaces, dashes and brackets are stripped, and the result
11	 * must carry 8 to 15 digits after the {@code '+'}.
12	 *
13	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
14	 * becomes {@code "+6421123456"}.
15	 *
16	 * <p>Where the country code has a known fixed national-number length, that length is enforced:
17	 * {@code +61} requires 9 national digits and {@code +1} requires 10. A number whose national
18	 * part is the wrong length for its country code is rejected. Country codes with no known rule
19	 * are constrained only by the general 8-to-15-digit bound.
20	 */
21	final class E164Telephone {
22	
23	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
24	    private static final String DEFAULT_COUNTRY_CODE = "61";
25	
26	    /** Spaces, dashes and brackets, which carry no meaning in E.164. */
27	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
28	
29	    /** A valid E.164 body: 8 to 15 digits following the {@code '+'}. */
30	    private static final Pattern E164_DIGITS = Pattern.compile("\\d{8,15}");
31	
32	    private E164Telephone() {
33	    }
34	
35	    /**
36	     * @param raw the telephone as supplied by the client.
37	     * @return the E.164 string (e.g. {@code "+61412345678"}), or {@code null} if {@code raw}
38	     *         cannot form a valid E.164 number.
39	     */
40	    static String format(String raw) {
41	        if (raw == null) {
42	            return null;
43	        }
44	        String cleaned = SEPARATORS.matcher(raw).replaceAll("");
45	        String digits;
46	        if (cleaned.startsWith("+")) {
47	            digits = cleaned.substring(1);
48	        }
49	        else {
50	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
51	            digits = DEFAULT_COUNTRY_CODE + national;
52	        }
53	        if (!E164_DIGITS.matcher(digits).matches() || !hasValidNationalLength(digits)) {
54	            return null;
55	        }
56	        return "+" + digits;
57	    }
58	
59	    /**
60	     * Checks the national-number length against the number's country code, taken as the longest
61	     * known country-code prefix of {@code digits}.
62	     *
63	     * @param digits the E.164 body (country code plus national number, no {@code '+'}).
64	     * @return {@code false} only when {@code digits} starts with a country code that has a known
65	     *         national-number length and the national part does not match it; {@code true} for
66	     *         country codes without a known rule.
67	     */
68	    private static boolean hasValidNationalLength(String digits) {
69	        String countryCode = E164.countryCodeOf(digits);
70	        if (countryCode == null) {
71	            return true;
72	        }
73	        return digits.length() - countryCode.length() == E164.nationalLength(countryCode);
74	    }
75	}
