1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Marks a new owner joining an already-occupied household as a <em>declared</em> member when the
11	 * request opts in with {@code sharesHousehold=true}. A household is keyed on (last name, postcode) via
12	 * the deterministic {@link Owner#getHouseholdId() householdId}, so additional members are admitted
13	 * — a second owner is not a duplicate as long as its identity (telephone) differs, which
14	 * {@link EnsureUniqueIdentity} enforces. What differs is intent: a declared member is deliberate, so
15	 * this step publishes {@link DeclaredHouseholdMember} to tell {@link DetectPossibleDuplicate} to leave
16	 * it unflagged. An undeclared owner joining an occupied household is admitted too, but stays a
17	 * suspected soft duplicate.
18	 *
19	 * <p>Runs after {@link AssignHouseholdId} so the owner carries its final id, and before
20	 * {@link DetectPossibleDuplicate}. An owner without a postcode belongs to no household, so nothing is
21	 * marked.
22	 */
23	public class MarkDeclaredHouseholdMember {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository,
26	            Out<DeclaredHouseholdMember> declaredMember) {
27	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return;
29	        }
30	        boolean occupied = Household.existingMembers(owner, ownerRepository).stream()
31	                .anyMatch(existing -> !existing.isDeleted());
32	        if (occupied) {
33	            declaredMember.set(DeclaredHouseholdMember.INSTANCE);
34	        }
35	    }
36	}
