package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate check for creating an owner: rejects a request whose derived
 * {@link Owner#getIdentityKey() identity key} — normalized telephone, email and household id — equals
 * that of an existing owner. It subsumes the former separate telephone, email and household checks:
 * because the telephone is part of the key, two members of one household with different telephones
 * have different keys and are both allowed; only an exact full-key match is a duplicate.
 *
 * <p>Runs after {@link AssignHouseholdId} so the new owner carries its final {@code householdId}, and
 * before {@link SaveOwner} so a collision is rejected with 409 before anything is persisted. Only
 * owners sharing the (already normalized) telephone can share the whole key, so those are the
 * candidates compared.
 */
public class EnsureUniqueIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateIdentityException {
        String identityKey = owner.getIdentityKey();
        for (Owner existing : ownerRepository.findByTelephone(owner.getTelephone())) {
            if (!existing.isDeleted() && identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}

package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request has the same derived identity key (normalized telephone, email
 * and household id) as an existing owner. This single key subsumes the former separate telephone,
 * email and household duplicate checks. Handled by {@link DuplicateIdentityExceptionHandler}, which
 * responds 409 Conflict.
 */
public class DuplicateIdentityException extends Exception {

    public DuplicateIdentityException(String identityKey) {
        super("Identity key is already in use: " + identityKey);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps a newly built owner with its deterministic {@code householdId}, derived from its last name
 * and postcode (see {@link Household}). Because the id is a pure function of those two values, owners
 * that share a last name and postcode share the id automatically — no explicit opt-in creates the
 * link. An owner without a postcode belongs to no household and is left without an id.
 *
 * <p>Runs under the request transaction, after {@link BuildOwner}, so later steps that key off the
 * household ({@link MarkDeclaredHouseholdMember}, {@link CountHouseholdMembers},
 * {@link EnsureUniqueIdentity} via the identity key) see the final id.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Household.idFor(owner.getLastName(), owner.getPostcode()));
    }
}

